-- 024: brand-choice guides hide 'Aftermarket options' once a brand is chosen (variants.options[].brand)
update guides set content = $j${"id": "intake-aftermarket", "title": "Aftermarket intake install", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "intake-hero", "alsoFits": "2006–08.5 GTI/Jetta/Eos 2.0T FSI · 06–08 A3 8P · 08 TT 8J (same engine-cover airbox)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake are you installing?", "hint": "They are not all the same job. Most kits remove the engine cover entirely and put a heat-shielded filter on the battery tray. APR's Carbonio keeps the stock airbox and engine cover.", "options": [{"id": "ie", "label": "Integrated Engineering (IE)", "when": "Full kit: pipe, heat shield, filter. Engine cover comes off.", "brand": true}, {"id": "neuspeed", "label": "Neuspeed P-Flo", "when": "Full kit with heat shield on three battery-tray posts. Engine cover comes off.", "brand": true}, {"id": "carbonio", "label": "APR Carbonio (Stage 1 / Stage 2)", "when": "Keeps the engine cover. Stage 1 swaps the lower airbox and scoop; Stage 2 swaps the turbo inlet pipe.", "brand": true}, {"id": "other", "label": "Other sealed-box cone kit (CTS, Injen, K&N…)", "when": "Same shape of job as IE. Follow your kit's sheet for hardware.", "brand": false}], "brandSpecific": true}, "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–600", "risk": "MAF sensor is fragile · clamps at the turbo are awkward", "why": "On a stock turbo, an intake is mostly sound and throttle feel: the forums are blunt about that. Pair it with a tune or a bigger turbo and it starts to earn its keep. Either way it's a satisfying afternoon that makes the car sound like it means it.", "note": "Manufacturer sheets say an hour. Owners report two, mostly spent making the turbo-side clamp reachable."}, "heroCap": "Air path after the swap: filter under a heat shield on the battery tray, metal pipe past the factory MAF sensor, silicone coupler onto the turbo inlet. The engine cover is gone.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first engine mod, often with a Stage 1 tune"], "earliest": null, "detail": "There's nothing to wear out; owners do it for sound and looks first, and because a tune plus intake is the classic first step. Oiled cotton filters want cleaning every 20–30k; dry paper elements get replaced.", "factors": ["Stage 1/2 tune", "K04 or bigger turbo (then it matters for real)", "You miss induction noise"], "inspect": ["Cotton filter: clean and re-oil every 20–30k miles, lightly. Over-oiling fouls the MAF."], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor notes. Power claims are the vendors'."}}, "should": {"yesIf": ["You want induction sound and sharper throttle feel", "You're tuned or going to be", "You have or want to delete the engine cover look", "You accept that dyno gains on a stock turbo are small"], "codes": [], "notes": ["The factory MAF sensor moves to the new pipe. Every good kit sizes its pipe to the factory MAF housing so fuel trims stay right; a pipe that doesn't will throw codes. That's why the cheap eBay pipe is a bad idea.", {"text": "Carbonio Stage 1 is the mild version: the engine cover and factory filter stay, only the lower airbox and scoop change. Owners who wanted full-intake gains were disappointed; owners who wanted to keep the cover were happy. Know which one you are.", "only": ["carbonio"]}], "confidence": {"level": "high", "n": 4, "note": "Method agrees across two manufacturer PDFs and two owner install threads."}}, "parts": [{"tier": "aftermarket", "name": "Intake kit", "pn": "the kit you chose above", "note": "Pipe, coupler(s), filter, heat shield, clamps, isolator hardware", "price": "$250–600", "links": []}, {"tier": "oe", "name": "Turbo inlet o-ring / gasket", "pn": "if reusing the factory inlet pipe", "note": "Only if it's cracked", "price": "$5", "links": [], "only": ["carbonio"]}, {"tier": "oe", "name": "Small zip ties, silicone spray", "pn": "—", "note": "For routing the MAF harness and seating grommets", "price": "$5", "links": []}], "aftermarket": [{"name": "Integrated Engineering carbon/aluminium intake", "note": "Complete, well-documented kit; the install PDF is the best of the group. Velocity stack under a powder-coated heat shield.", "price": "$450–550", "signal": "Best documented", "links": [{"store": "IE install guide (PDF)", "url": "https://pbie.s3.amazonaws.com/guides/IE%20MK5%20FSI%20INTAKE%20INSTALL%20IEINCB4.pdf"}]}, {"name": "Neuspeed P-Flo", "note": "The long-time forum default. Aluminium heat shield, choice of oiled cotton or dry paper filter, CARB exempt. Pipe matched to the factory MAF.", "price": "$300–350", "signal": "Forum favorite", "links": []}, {"name": "APR Carbonio Stage 1 (+ Stage 2 pipe)", "note": "Carbon fibre, keeps the engine cover. Stage 1 is the airbox/scoop; Stage 2 adds the turbo inlet pipe, which owners found fiddlier and prone to sagging without its centre support.", "price": "$300–600", "signal": "Best looking, mildest", "links": []}, {"name": "CTS Turbo", "note": "Sealed airbox with scoop, 2.75\" pipe, factory MAF position, bungs for their BOSS kit. Popular with the tuned/K04 crowd.", "price": "$300–400", "signal": "Tuner pick", "links": [{"store": "CTS Turbo", "url": "https://ctsturbo.com/product/cts-turbo-mk5-mk6-s3-air-intake-system/"}]}], "tools": [{"name": "T20 and T25 Torx", "note": "kits and cars disagree on which; bring both"}, {"name": "Flat screwdriver (inlet clips), Phillips", "only": ["ie", "neuspeed", "other", "carbonio"]}, {"name": "Pliers or spring-clamp tool for the turbo inlet hose clamp"}, {"name": "4mm hex (MAF screws in the new pipe), 10mm wrench (isolator stud)", "only": ["ie", "neuspeed", "other"]}, {"name": "5mm hex (lower airbox bolt), T30 (inlet pipe bolt), 10mm socket", "only": ["carbonio"]}, {"name": "Screwdriver or ¼\" driver for worm clamps; a mirror helps at the turbo"}], "before": ["Engine cold. You'll have your hands next to the turbo.", "Lay the kit out and check every clamp and coupler against the parts list before you take anything apart.", "The MAF sensor's element is exposed and delicate. Handle it by the housing, never touch the wires, and keep it off the ground."], "steps": [{"n": 1, "title": "Open up the stock intake", "blocks": [{"t": "text", "b": "Pull the inlet cover off the radiator support (a locking tab each side). Separate the two halves of the air inlet by pressing their tabs. Unplug the MAF sensor. Flip the two clips on the turbo inlet pipe with a flat screwdriver and pull it off the engine cover.", "only": ["ie", "neuspeed", "other"]}, {"t": "text", "b": "Unscrew the eight to ten Phillips screws holding the airbox top to its bottom (the engine cover is the top). Unplug the MAF and release the hose clamp between the MAF and the turbo inlet pipe. Lift the top off and set it aside; you're keeping it.", "only": ["carbonio"]}]}, {"n": 2, "title": "Engine cover off, radiator-support inlet off", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Grab the cover at the corners and pull straight up off its four grommets; it can take real leverage. Then remove the last piece of the inlet from the radiator support (two T25 screws). Squeeze the turbo inlet hose clamp with pliers and pull the factory inlet pipe off the turbo."}, {"t": "ill", "id": "airbox-bay", "cap": "Everything that comes out. The MAF sensor (blue) is the one part you keep."}]}, {"n": 2, "title": "Lower airbox and scoop off", "only": ["carbonio"], "blocks": [{"t": "text", "b": "With the top gone, remove the two Torx screws holding the inlet scoop (T25 on most cars, whatever APR's sheet says). Remove the 5mm hex bolt holding the lower airbox to the car, then pull the lower airbox up firmly off its two rubber-grommeted studs."}]}, {"n": 3, "title": "Move the MAF sensor to the new pipe", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Two T20 screws hold the MAF in the engine cover. Lift it out by the housing. Set it into the new pipe's MAF boss in the same orientation (arrow or airflow marking toward the turbo) and fix it with the kit's button-head screws (4mm hex on IE). Snug, not tight; the housing is plastic."}, {"t": "warn", "b": "If the sensor is dropped or the wires touched, you'll chase a rough idle for weeks. It's the one fragile part in this job."}]}, {"n": 3, "title": "Fit the Carbonio airbox and scoop", "only": ["carbonio"], "blocks": [{"t": "text", "b": "Seat the carbon lower airbox onto the two studs, fit APR's scoop with the two Torx screws, and put the original engine cover back on top with the Phillips screws and the factory filter. Reconnect the MAF and the inlet hose clamp. Stage 1 is done; if you have the Stage 2 pipe, continue."}]}, {"n": 4, "title": "Coupler onto the turbo", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Slip the kit's silicone coupler onto the turbo inlet with its clamp loose. If the factory breather hose used to plug into the inlet pipe, fit the kit's plug into that coupler port with its one-time clamp and crimp it tight. Leave the main clamps loose for now."}]}, {"n": 4, "title": "Stage 2: swap the turbo inlet pipe", "only": ["carbonio"], "blocks": [{"t": "text", "b": "Remove the T30 bolt securing the factory inlet pipe at the rear of the head (APR calls it T25; it's T30), unclip the breather hose, and release the hose clamp at the turbo coupler with pliers; it's a tight reach. Fit the carbon pipe onto the coupler, reconnect the breather, and start the 10mm bolt with its rubber washer at the rear mount."}, {"t": "note", "b": "The pipe passes close to the brake fluid reservoir and brake lines. If it touches, loosen the turbo-side clamp and push the pipe further onto the coupler. Fit the centre support APR supplies; without it the pipe sags onto the brake lines and vibrates."}]}, {"n": 5, "title": "Pipe and isolator", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Fit the rubber isolator stud to the pipe's bracket (washer and 10mm nut, hand tight), then guide the pipe into the turbo coupler with its clamp loose. Pass the isolator stud through the vacuum-pump bracket on the side of the head and start its nut. Nothing tight yet."}]}, {"n": 6, "title": "Heat shield and filter", "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Press the kit's rubber grommets into the heat shield (flat side down), fit the velocity-stack coupler to the shield with its clamp loose, and lower the shield onto the battery-tray posts (two on IE, three on Neuspeed) until the grommets click over. Join the shield coupler to the pipe. Wipe the inside lip of the filter with cleaner so it grips, then clamp it to the stack."}, {"t": "ill", "id": "intake-hero", "cap": "Final layout. Every clamp is still loose until the whole run sits relaxed."}]}, {"n": 7, "title": "Align, then tighten everything", "caution": true, "only": ["ie", "neuspeed", "other"], "blocks": [{"t": "text", "b": "Stand back and look: the pipe should sit straight with no coupler under tension and nothing touching the strut brace, coolant lines or the battery. Adjust, then tighten all clamps firmly (a screwdriver on worm clamps; no impact), both isolator nuts with a 10mm, and plug the MAF back in. Tug the whole thing; nothing should move."}, {"t": "warn", "b": "A coupler clamped under tension slips off the turbo inlet under boost, and the car eats unfiltered air until you notice. Relaxed first, tight second."}]}, {"n": 8, "title": "Start it and listen", "blocks": [{"t": "text", "b": "Start the engine. Rev gently and listen for hissing at the couplers. Let it idle for a couple of minutes; a stumble that settles is the ECU adapting, one that doesn't is a MAF problem. Take it for a drive and re-check every clamp when you're back."}]}], "alsoReplace": [{"name": "PCV / breather system", "why": "You're handling the breather hose anyway. A tired FSI PCV is a known oil-consumption culprit; a revision or a catch-can install shares this access."}, {"name": "Turbo inlet pipe coupler", "why": "If the factory coupler at the turbo is hardened or cracked, the kit's silicone one replaces it; check before you assume you're reusing it.", "only": ["carbonio"]}], "check": {"tab": "Which kit?", "title": "Which kind of intake suits you?", "illId": "intake-hero", "illCap": "Full kit (left) replaces the cover; Carbonio (right) keeps it.", "rows": [{"see": "Stock turbo, maybe Stage 1, want sound and looks", "means": "You're buying character, not horsepower. Any well-made kit does this.", "do": "Neuspeed or IE if you like the exposed-engine look; Carbonio Stage 1 if you want the cover."}, {"see": "K04 or bigger turbo, Stage 2+", "means": "Now the stock box is a real restriction.", "do": "Full kit: IE, CTS or Neuspeed. Skip Carbonio Stage 1."}, {"see": "Salt-belt daily, don't want to oil filters", "means": "Oiled cotton needs care and can foul the MAF.", "do": "Pick a kit with a dry filter option (Neuspeed) or budget for careful oiling."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; vendor claims noted as claims."}}, "aftercare": ["Re-tighten clamps after the first heat cycle.", "Oiled filter: clean and lightly re-oil every 20–30k. Dry filter: replace per the maker.", "Rough idle after install: check the MAF plug and that the pipe's MAF boss is the right diameter for your sensor."], "disagreements": [{"topic": "How much does it do?", "pos": "Vendors: 9–15 whp. Owners: 'louder, not faster' on a stock turbo.", "call": "Both are right for different cars. We say so."}, {"topic": "T20 or T25? T25 or T30?", "pos": "APR's sheet vs the owner who installed it; Pelican vs FCP on the stock screws.", "call": "Bring the set."}, {"topic": "Is Carbonio Stage 1 an intake?", "pos": "Forum argument since 2008.", "call": "It's the mild option. Fine if you want the cover; not the pick for a K04."}], "sources": ["IE Cold Air Intake install guide (PDF)", "Neuspeed P-Flo install guide and product pages", "VWVortex APR/Carbonio Stage 1 & 2 install thread", "GolfMKV and Golfmk6 Carbonio threads", "CTS Turbo product page", "VWVortex and Golfmk6 intake-value threads"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'intake-aftermarket';
update guides set content = $j${"id": "intake-tsi", "title": "Aftermarket intake install (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "airbox-tsi", "alsoFits": "Mk6 GTI/Golf TSI, Mk5 Jetta TSI, Mk2 Beetle (same airbox and inlet)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake are you installing?", "hint": "TSI kits are engine-specific: an FSI intake will not fit. All of the common ones remove the side airbox and reuse its mounting points.", "options": [{"id": "ie", "label": "Integrated Engineering (TSI)", "when": "Full kit; PDF install guide", "brand": true}, {"id": "cts", "label": "CTS Turbo", "when": "Full kit; brief sheet", "brand": true}, {"id": "other", "label": "Other TSI kit (APR, Neuspeed, ECS…)", "when": "Same shape of job; follow your kit's sheet", "brand": false}], "brandSpecific": true}, "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–600", "risk": "MAF sensor is fragile · clamps at the turbo are awkward", "why": "Same story as the FSI: on a stock turbo it's sound and throttle feel; with a tune it earns its keep. The TSI's side airbox makes the swap simpler than on the FSI because the engine cover isn't involved.", "note": "IE's TSI PDF and owners agree on about an hour."}, "heroCap": "TSI kits replace the side airbox with a heat-shielded filter on the factory airbox mounts and a pipe to the turbo inlet. The engine cover stays.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first engine mod, often with a Stage 1 tune"], "earliest": null, "detail": "There's nothing to wear out; owners do it for sound and looks first, and because a tune plus intake is the classic first step. Oiled cotton filters want cleaning every 20–30k; dry paper elements get replaced.", "factors": ["Stage 1/2 tune", "K04 or bigger turbo (then it matters for real)", "You miss induction noise"], "inspect": ["Cotton filter: clean and re-oil every 20–30k miles, lightly. Over-oiling fouls the MAF."], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor notes. Power claims are the vendors'."}}, "should": {"yesIf": ["You want induction sound and sharper throttle feel", "You're tuned or going to be", "You have or want to delete the engine cover look", "You accept that dyno gains on a stock turbo are small"], "codes": [], "notes": ["The factory MAF sensor moves to the new pipe. Pipe bore must match the sensor or fuel trims go off; buy a real kit, not an eBay pipe.", "Check the fitment: 2.0T FSI and 2.0T TSI intakes are not interchangeable, and both were sold for 'Mk5 GTI'. Your 2008.5–2009 car is TSI."], "confidence": {"level": "high", "n": 4, "note": "Method agrees across two manufacturer PDFs and two owner install threads."}}, "parts": [{"tier": "aftermarket", "name": "Intake kit", "pn": "the kit you chose above", "note": "Pipe, coupler(s), filter, heat shield, clamps, isolator hardware", "price": "$250–600", "links": []}, {"tier": "oe", "name": "Turbo inlet o-ring / gasket", "pn": "if reusing the factory inlet pipe", "note": "Only if it's cracked", "price": "$5", "links": [], "only": ["carbonio"]}, {"tier": "oe", "name": "Small zip ties, silicone spray", "pn": "—", "note": "For routing the MAF harness and seating grommets", "price": "$5", "links": []}], "aftermarket": [{"name": "Integrated Engineering TSI intake", "note": "Uses the factory airbox mounts; velocity stack under a heat shield; full PDF.", "price": "$400–500", "signal": "Best documented", "links": [{"store": "IE TSI install guide (PDF)", "url": "https://pbie.s3.amazonaws.com/guides/IE%20MK5_MK6%20TSI%20IEINCC2%20Intake%20Install%20Guide.pdf"}]}, {"name": "CTS Turbo TSI intake", "note": "Sealed box with scoop, 2.75\" pipe, factory MAF position. Sheet is short but the job matches IE's.", "price": "$300–400", "signal": "Tuner pick", "links": [{"store": "CTS sheet (PDF)", "url": "http://blog.moddedeuros.com/wp-content/uploads/2020/12/CTS-IT-105R.pdf"}]}, {"name": "APR Carbonio / Neuspeed P-Flo / ECS Luft-Technik (TSI versions)", "note": "All reuse the airbox mounts; same install shape. Buy the TSI part number.", "price": "$300–600", "signal": "Fine choices", "links": []}], "tools": [{"name": "T25 Torx, 8mm triple-square (inlet pipe bracket bolt)"}, {"name": "Hose-clamp pliers, Phillips (MAF screws), 10mm wrench"}, {"name": "Screwdriver for worm clamps; mirror for the turbo inlet"}], "before": ["Engine cold.", "Lay the kit out against its parts list.", "Handle the MAF by its housing only."], "steps": [{"n": 1, "title": "Intake duct off", "blocks": [{"t": "text", "b": "Two T25 screws hold the duct to the radiator support, one each side. Unclip the duct's plastic lid and lift the duct out."}]}, {"n": 2, "title": "MAF and inlet pipe", "blocks": [{"t": "text", "b": "Unplug the MAF. Squeeze the spring clamp holding the inlet pipe to the MAF and slide it back onto the pipe; pull the pipe off the MAF. Cars with secondary air injection: unclip the SAI hose from the airbox."}]}, {"n": 3, "title": "Airbox out", "blocks": [{"t": "text", "b": "One T25 at the back of the airbox, then pull the whole box straight up off its rubber mounts. Two screws hold the MAF into the box; slide the sensor out and set it somewhere clean."}, {"t": "ill", "id": "airbox-tsi", "cap": "The box lifts off two or three rubber-mounted posts; the kit's heat shield lands on the same posts."}]}, {"n": 4, "title": "Factory inlet pipe off", "blocks": [{"t": "text", "b": "Remove the inlet pipe's bracket bolt (8mm triple-square) and the clamp at the turbo coupler, and pull the factory inlet pipe. Keep the clamp if the kit reuses it."}]}, {"n": 5, "title": "Build and fit the kit", "blocks": [{"t": "text", "b": "MAF into the new pipe with the kit's screws, arrow toward the turbo. Coupler onto the turbo inlet, clamp loose. Pipe into the coupler, kit bracket onto the factory bracket point. Heat shield onto the airbox posts. Filter onto the pipe or stack, clamp snug. Reconnect the breather/SAI hose to the kit's fitting.", "only": ["ie", "cts", "other"]}]}, {"n": 6, "title": "Align, tighten, start", "caution": true, "blocks": [{"t": "text", "b": "Everything sitting relaxed and clear of the strut brace and coolant lines? Then tighten all clamps and the bracket, plug the MAF in, and start it. Listen for hiss at the couplers; a stumble that clears in a minute is the ECU adapting."}, {"t": "warn", "b": "A coupler clamped under tension slips off the turbo under boost. Relaxed first, tight second."}]}], "alsoReplace": [{"name": "PCV valve", "why": "Different part on the TSI and just as failure-prone. Same access."}, {"name": "Turbo inlet coupler", "why": "Hardened factory couplers are a common TSI boost leak; the kit's silicone one replaces it."}], "check": {"tab": "Which kit?", "title": "Which kind of intake suits you?", "illId": "intake-hero", "illCap": "Full kit (left) replaces the cover; Carbonio (right) keeps it.", "rows": [{"see": "Stock turbo, maybe Stage 1, want sound and looks", "means": "You're buying character, not horsepower. Any well-made kit does this.", "do": "Neuspeed or IE if you like the exposed-engine look; Carbonio Stage 1 if you want the cover."}, {"see": "K04 or bigger turbo, Stage 2+", "means": "Now the stock box is a real restriction.", "do": "Full kit: IE, CTS or Neuspeed. Skip Carbonio Stage 1."}, {"see": "Salt-belt daily, don't want to oil filters", "means": "Oiled cotton needs care and can foul the MAF.", "do": "Pick a kit with a dry filter option (Neuspeed) or budget for careful oiling."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; vendor claims noted as claims."}}, "aftercare": ["Re-tighten clamps after the first heat cycle.", "Oiled filter: clean and lightly re-oil every 20–30k. Dry filter: replace per the maker.", "Rough idle after install: check the MAF plug and that the pipe's MAF boss is the right diameter for your sensor."], "disagreements": [{"topic": "How much does it do?", "pos": "Vendors: 9–15 whp. Owners: 'louder, not faster' on a stock turbo.", "call": "Both are right for different cars. We say so."}, {"topic": "T20 or T25? T25 or T30?", "pos": "APR's sheet vs the owner who installed it; Pelican vs FCP on the stock screws.", "call": "Bring the set."}, {"topic": "Is Carbonio Stage 1 an intake?", "pos": "Forum argument since 2008.", "call": "It's the mild option. Fine if you want the cover; not the pick for a K04."}], "sources": ["IE Mk5/Mk6 TSI intake install guide (PDF)", "CTS Turbo Mk6 intake sheet (Mk5 TSI shown)", "Forum threads on TSI intakes"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'intake-tsi';
update guides set content = $j${"id": "intake-r32", "title": "Aftermarket intake (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "airbox-tsi", "alsoFits": "Mk5 R32 only (Mk4 R32 and A3/TT 3.2 kits differ)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake?", "hint": "All the R32 kits replace the airbox with a filter on a pipe to the throttle body and move the factory MAF into the new pipe.", "options": [{"id": "neuspeed", "label": "Neuspeed P-Flo", "when": "Filter on a short pipe; heat shield; the most common.", "brand": true}, {"id": "carbonio", "label": "APR Carbonio", "when": "Carbon pipe; premium; same layout.", "brand": true}, {"id": "other", "label": "VF / BSH / Evolution / other", "when": "Same shape; follow the kit sheet.", "brand": false}], "brandSpecific": true}, "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$300–600", "risk": "MAF handling · clamps under tension", "why": "On a naturally aspirated VR6 an intake is mostly about the noise, and the noise is the reason people buy an R32. Power gains are a handful of horsepower up top; the induction howl is immediate. The factory airbox lifts out on clips, so this is one of the easier jobs on the car.", "note": "FCP's R32 valve-cover write-up confirms the airbox is clips and tabs; kit sheets from Neuspeed and APR cover the rest."}, "heroCap": "Factory airbox at the front-left of the bay on clips, a duct to the throttle body with the MAF in it. Kits replace the box and duct with a filter and a pipe; the MAF moves over.", "lifespan": {"title": "When owners do this", "headline": ["Early. It's the R32 mod."], "earliest": null, "detail": "Nothing wears out; owners do it for sound. Some go back to stock for heat-soak reasons in summer; a kit with a real heat shield helps.", "factors": ["Want the noise", "Heat soak in traffic (pick a shielded kit)"], "inspect": ["Filter every oil change"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus."}}, "should": {"yesIf": ["You want the VR6 to sound like a VR6", "Replacing a tired factory airbox anyway"], "codes": [], "notes": ["The MAF is a slot sensor in a housing; the kit's pipe must match its bore or the car runs lean and throws codes. Real kits are designed for it.", "Oiled cotton filters: oil lightly or the MAF fouls. Dry filters avoid the question.", "Heat: the VR6 bay is hot. Kits with a proper shield around the filter (Neuspeed, Carbonio) keep intake temps sane in traffic."], "confidence": {"level": "medium", "n": 3, "note": "Kit documentation and owner threads."}}, "parts": [{"tier": "aftermarket", "name": "R32 intake kit", "pn": "the kit you chose above", "note": "Pipe, filter, shield, clamps, MAF adapter", "price": "$300–600", "links": []}], "aftermarket": [{"name": "Neuspeed P-Flo (Mk5 R32)", "note": "Short pipe, dry filter, heat shield on the factory airbox mounts. The forum default; good sheet.", "price": "$300–350", "signal": "Forum favorite", "links": []}, {"name": "APR Carbonio", "note": "Carbon-fibre pipe and box, premium finish, retains a shielded enclosure.", "price": "$500–600", "signal": "Premium", "links": []}, {"name": "VF Engineering / BSH / Evolution Motorsports", "note": "Same layout, different hardware. VF's is well regarded on the 3.2 TT.", "price": "$350–500", "signal": "Alternatives", "links": []}], "tools": [{"name": "Flat screwdriver for the clamps; T25; pliers for the breather hose"}, {"name": "Phillips for the MAF screws (handle the sensor by its housing)"}], "before": ["Engine cold.", "Lay the kit out against its list.", "Note where the breather hose from the valve cover joins the factory duct; the kit has a port for it."], "steps": [{"n": 1, "title": "Factory box out", "blocks": [{"t": "text", "b": "Unplug the MAF. Loosen the clamp at the throttle body and pull the duct off. Disconnect the breather hose from the duct. The airbox sits in the chassis on clips and tabs: release the clips and lift the whole box and duct out as one piece."}, {"t": "ill", "id": "airbox-tsi", "cap": "Same corner of the bay as the drawing; the R32 box lifts out on clips rather than screws."}]}, {"n": 2, "title": "MAF across", "blocks": [{"t": "text", "b": "Two screws hold the MAF into the factory duct. Slide it out and into the kit's pipe with the kit's screws, arrow toward the throttle body. Housing only; don't touch the element."}]}, {"n": 3, "title": "Kit in", "blocks": [{"t": "text", "b": "Heat shield onto the factory airbox mounts (Neuspeed, Carbonio) or the kit's bracket. Coupler onto the throttle body, clamp loose. Pipe into the coupler, filter onto the pipe, clamp loose. Breather hose to the kit's port.", "only": ["neuspeed", "carbonio", "other"]}]}, {"n": 4, "title": "Relax, then tighten", "caution": true, "blocks": [{"t": "text", "b": "Everything sitting with no twist, filter clear of the fender liner and the coolant reservoir? Now tighten every clamp. MAF plugged in. Start it; a stumble for a minute is the ECU adapting."}, {"t": "warn", "b": "A coupler tightened under tension pops off the throttle body on the first hard pull. Relaxed first, tight second."}]}], "alsoReplace": [{"name": "Spark plugs and coils", "why": "The engine cover's off and you've heard the induction noise; a misfire will ruin it. If they're due, now."}], "check": {"tab": "Which kit?", "title": "Which kit?", "illId": "airbox-tsi", "illCap": "Sound first; shielding second.", "rows": [{"see": "Want the sound, daily driver", "means": "A shielded kit.", "do": "Neuspeed P-Flo."}, {"see": "Want it to look the part under the hood", "means": "Carbon.", "do": "APR Carbonio."}, {"see": "Budget", "means": "Any real kit beats an eBay pipe: the MAF bore matters.", "do": "VF or BSH used."}], "c": {"level": "community", "n": 3, "note": "Owner threads."}}, "aftercare": ["Check clamps after a week.", "Filter cleaning per the maker."], "disagreements": [{"topic": "Power?", "pos": "Vendors claim 5–10 hp.", "call": "A few, at the top. Buy it for the noise."}], "sources": ["FCP Euro Mk5 R32 write-up (airbox removal)", "Neuspeed and APR R32 intake sheets and listings", "VWVortex R32 intake threads"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'intake-r32';
update guides set content = $j${"id": "catch-can", "title": "Oil catch can install", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "catchcan-hero", "alsoFits": "2.0T FSI (EA113) only: Mk5 GTI/Jetta, B6 Passat, Eos, A3 8P, Golf R Mk6 (kits are engine-specific)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which setup?", "hint": "Kits differ in where they tap the crankcase vent. ECS keeps the factory valve cover and adds an adapter plate under the PCV; IE and CTS replace the plastic breather plate; IE's billet valve cover replaces the cover itself.", "options": [{"id": "ecs", "label": "ECS kit (factory valve cover)", "when": "Adapter plate under the PCV, PCV cap at the manifold. Best documented.", "brand": true}, {"id": "ie", "label": "IE or CTS kit (factory valve cover)", "when": "Billet breather adapter replaces the plastic plate on the cover.", "brand": true}, {"id": "billet", "label": "IE billet valve cover + can", "when": "New cover with ports. Removes every plastic breather part. Biggest job.", "brand": true}], "brandSpecific": true}, "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$250–450 (kit) · $700+ with billet cover", "risk": "Routing under fuel lines · winter freeze", "why": "Direct injection means fuel never washes the intake valves. Oil vapour from the crankcase vent bakes onto them instead, and the FSI is famous for it: carbon buildup, lost power, rough idle by 80k. A catch can separates that oil out before it reaches the intake. It doesn't undo existing carbon, but it slows the next layer.", "note": "Vendors say under an hour; owners say two, mostly routing lines neatly. Straightforward either way."}, "heroCap": "Vent leaves the crankcase, passes through the baffled can where oil drops out, and clean vapour returns to the turbo inlet. Recirculated, so no mist in the engine bay and nothing vented to atmosphere.", "lifespan": {"title": "When owners do this", "headline": ["Usually with a tune, or after the first intake-valve carbon cleaning"], "earliest": null, "detail": "Nothing wears out; owners add a can once they understand the carbon problem, often at the same time as a PCV valve replacement since the parts overlap. Tuned cars run more crankcase pressure and make more vapour, so they benefit most.", "factors": ["Stage 2+ tune", "Cold climate short trips (more water in the vent)", "PCV valve failed again"], "inspect": ["Check the can weekly at first, then learn your interval. Empty it at about 2 inches of waste."], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor positioning; carbon-buildup mechanism is well established for direct injection."}}, "should": {"yesIf": ["Tuned car", "You've had or want to avoid intake-valve carbon cleaning", "Oil in the intercooler pipes", "Replacing the PCV valve anyway"], "codes": [], "notes": ["Recirculating kits (every one listed here) route clean vapour back to the turbo inlet. Vent-to-atmosphere setups with a little filter on the can are messy, smell, and are an emissions violation. Stay recirculated.", "Winter matters. Crankcase vapour is mostly water in cold weather; it collects in the can and lines and can freeze. ECS says drain weekly near freezing and reconnect the factory hose below freezing. Take that seriously: a frozen vent line pressurises the crankcase and blows seals."], "confidence": {"level": "high", "n": 3, "note": "Procedure and reasoning consistent across ECS, IE and CTS material."}}, "parts": [{"tier": "aftermarket", "name": "Catch can kit", "pn": "the kit you chose above", "note": "Can, bracket, lines with AN fittings, adapter plate or breather adapter, PCV cap", "price": "$250–450", "links": []}, {"tier": "aftermarket", "name": "IE billet valve cover", "pn": "IEBAVC5", "note": "Plus the matching can kit; the EVAP crossover relocation kit may be needed", "price": "$500+", "links": [], "only": ["billet"]}, {"tier": "oe", "name": "Valve cover gasket", "pn": "06F 103 483 D", "note": "New cover, new gasket", "price": "$25", "links": [], "only": ["billet"]}, {"tier": "oe", "name": "Clean engine oil for the o-rings, zip ties", "pn": "—", "note": "", "price": "—", "links": []}], "aftermarket": [{"name": "ECS baffled catch can kit", "note": "Adapter plate under the factory PCV, -10AN braided lines, bracket on the engine-mount stud, dipstick, serviceable baffles. 37-page install PDF with the winter warning.", "price": "$300–350", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_15317_Volkswagen_MK5_Golf_FSI_Oil_Catch_Can_Kit_Installation_r4.pdf"}]}, {"name": "IE recirculating kit (factory cover)", "note": "Billet breather adapter replaces the plastic plate on the valve cover, two -10AN hoses, T-handle drain, bracket on the passenger side. Owners: under an hour.", "price": "$300–400", "signal": "Cleanest install", "links": [{"store": "IE", "url": "https://eurosporttuning.com/ie-mk5-mk6-golf-r-2-0t-fsi-recirculating-catch-can-kit-for-oem-valve-cover/"}]}, {"name": "IE billet valve cover + can kit", "note": "Replaces the whole cover, removing the plastic breather plate and PCV. Needs the EVAP crossover relocation on some cars. The permanent fix for a tuned FSI.", "price": "$800–1,000", "signal": "Full solution", "links": [{"store": "IE", "url": "https://performancebyie.com/products/ie-billet-valve-cover-catch-can-kit-vw-audi-20t-fsi"}]}, {"name": "CTS Turbo kit", "note": "Breather adapter in place of the plastic plate, bracket, braided lines. Popular with the K04 crowd; brief install sheet.", "price": "$250–350", "signal": "Tuner pick", "links": []}, {"name": "034Motorsport billet can", "note": "Made for their other platforms; FSI owners adapt it with a breather adapter. Good hardware, more DIY.", "price": "$300+", "signal": "Mix-and-match", "links": []}], "tools": [{"name": "T25 and T30 Torx, 10mm socket with extension"}, {"name": "AN fitting wrench or adjustable wrench (tape the jaws), hose-clamp pliers, connector release tool"}, {"name": "Torque wrench reading 3–10 Nm", "only": ["ecs"]}, {"name": "T30, 10mm; valve cover bolt torque wrench (8–10 Nm); shop towels for oil", "only": ["billet"]}], "before": ["Engine cool. Read your kit's sheet alongside this; hardware and routing differ by brand.", "Lubricate every o-ring with clean engine oil before threading an AN fitting, and never over-tighten them: they strip.", "Route lines away from the belt, the exhaust side, and anything that moves."], "steps": [{"n": 1, "title": "Intake and cover off", "blocks": [{"t": "text", "b": "Inlet hose screws (T25) and clamp, MAF unplugged, two inlet-pipe clips, engine cover off its grommets (driver front, driver rear, passenger rear, passenger front, as ECS orders it, to avoid cracking it)."}]}, {"n": 2, "title": "Upper breather pipe off, cap the manifold", "only": ["ecs"], "blocks": [{"t": "text", "b": "Squeeze the retainers and pull the corrugated pipe off the PCV valve and the intake manifold. Oil the o-rings on the kit's PCV cap and push it onto the manifold port (or onto a boost tap if you have one) until fully seated, then fit its retaining clip. The manifold side is now closed."}]}, {"n": 2, "title": "Breather plate off", "only": ["ie"], "blocks": [{"t": "text", "b": "The plastic breather plate sits on the valve cover with the breather hose on it. Disconnect the hose and any lines, then remove the plate's T25 screws. Coil-pack connectors may need to be unplugged for clearance; note their order."}]}, {"n": 2, "title": "Old valve cover off", "only": ["billet"], "blocks": [{"t": "text", "b": "Unplug all four coil packs and pull the coils (see the plugs guide), disconnect the PCV pipes and breather hose, the EVAP line and any brackets on the cover, then the cover bolts in a spiral from the outside in. Lift the cover; the gasket may stick. Clean the head's sealing face with a plastic scraper and a rag.", "only": ["billet"]}, {"t": "warn", "b": "Nothing falls into an open cylinder head. Rag over the cam area while you clean the face, and count your tools.", "only": ["billet"]}]}, {"n": 3, "title": "Lower pipe and PCV valve out", "only": ["ecs"], "blocks": [{"t": "text", "b": "Release the lower breather pipe's four-point connector (see the PCV guide), then the four T25 screws, and lift the valve out. Keep the screws; they hold the adapter plate."}]}, {"n": 4, "title": "Reroute the vacuum line and air tube", "only": ["ecs"], "blocks": [{"t": "text", "b": "To make room for the lines: remove the three T30 screws on the vacuum-line and air-tube hold-down clamps, unplug the HPFP pressure-sensor connector and unclip the vacuum line from the fuel line, disconnect the air tube from the valve cover, flip the clamps as the PDF shows, slide the near clamp along the line to meet the air-tube bracket, and refit the screws so both lines now run the new path. Reconnect the sensor and clip."}, {"t": "note", "b": "This is the only fiddly part of the ECS kit and the reason it takes two hours rather than one. The PDF's before/after photos are worth having open."}]}, {"n": 5, "title": "Adapter plate on, lines under the fuel lines", "only": ["ecs"], "blocks": [{"t": "text", "b": "Oil the 90° fitting on the feed line and thread it into the bottom of the adapter plate by hand, snug. Guide the feed line (plate attached) under the vacuum tube, under the engine-cover bracket and under the fuel lines. Fit the plate with the factory screws, reconnect the lower breather pipe to it. Route the return line the same way and thread it into the plate's side port."}, {"t": "torque", "label": "Adapter plate screws (T25 ×4)", "nm": 3.4, "c": {"level": "single", "n": 1, "note": "ECS: 3.4 Nm (30 in-lb). Snug; plastic and aluminium."}}]}, {"n": 5, "title": "Breather adapter on", "only": ["ie"], "blocks": [{"t": "text", "b": "Fit the kit's billet adapter where the plastic plate was, with its gasket or o-ring, using the factory or supplied screws, snug. Thread the two -10AN hose ends into it by hand with oiled o-rings. Reconnect the coil packs in order."}]}, {"n": 5, "title": "New cover on", "only": ["billet"], "blocks": [{"t": "text", "b": "New gasket into the billet cover's groove, cover onto the head, bolts snug in a spiral from the centre out, then torque per IE's sheet (factory spec is about 10 Nm). Reinstall coils and connectors. Fit the block breather adapter and thread the can's hoses into the cover ports. If the EVAP crossover fouls the new cover, IE's relocation kit moves it."}, {"t": "torque", "label": "Valve cover bolts", "nm": 10, "c": {"level": "single", "n": 1, "note": "Factory-style value; follow IE's sheet for their cover."}}]}, {"n": 6, "title": "Mount the can", "blocks": [{"t": "text", "b": "Bracket onto the stud on the end of the engine-mount bolt and the threaded hole in the body (clean it; don't strip the paint off the threads), bolt and nut to 10 Nm. Can into the bracket with the reservoir loose so it can rotate while you connect the hoses.", "only": ["ecs"]}, {"t": "text", "b": "Kit bracket to its mounting point (passenger side on IE, per the sheet on CTS); can into the bracket loose enough to rotate.", "only": ["ie", "billet"]}, {"t": "torque", "label": "Bracket bolt and nut", "nm": 10, "c": {"level": "single", "n": 1, "note": "ECS figure; other kits say snug."}, "only": ["ecs"]}]}, {"n": 7, "title": "Connect and route the lines", "caution": true, "blocks": [{"t": "text", "b": "Feed line to the can's feed side, return line to the return side (they're marked, and the baffles only work one way). Oil the o-rings, thread by hand, snug with a taped wrench. Then look at every inch of both lines: under the fuel lines, clear of brackets, no contact with anything that vibrates or gets hot. Adjust, then lock the can by tightening its reservoir."}, {"t": "ill", "id": "catchcan-hero", "cap": "Feed side has the holed baffle; return side is a flat plate. Backwards means the can does nothing."}, {"t": "warn", "b": "A line rubbing a bracket wears through in months, and a crankcase vent open to the bay is an oil mess plus a lean condition. Ten minutes of routing now."}]}, {"n": 8, "title": "Cover on, start, check", "blocks": [{"t": "text", "b": "Engine cover back on (check the hoses clear it), inlet pipe, MAF. Start it, listen for hiss at any fitting, check for a steady idle. Drive it a week, then pull the dipstick or open the drain and see what you caught."}]}], "alsoReplace": [{"name": "PCV valve", "why": "With the ECS kit the factory valve is removed anyway; with the others it stays. If it stays and it's original, replace it now."}, {"name": "Breather hoses and pipes", "why": "Brittle plastic clips; if any are cracked, new ones now."}, {"name": "Intake-valve carbon cleaning", "why": "The can slows new buildup; it doesn't remove old. On a 100k car with rough idle, a walnut-blast cleaning is the companion job."}], "check": {"tab": "Which path?", "title": "Which setup fits you?", "illId": "catchcan-hero", "illCap": "All three end up in the same place: vent through a can, back to the turbo inlet.", "rows": [{"see": "Stock-ish car, want the documented route", "means": "ECS keeps the factory cover and has a full PDF.", "do": "ECS kit. Replace the PCV valve while it's out."}, {"see": "Tuned, want the tidiest install under an hour", "means": "Breather adapter kits are the least intrusive.", "do": "IE or CTS kit."}, {"see": "Tuned, tired of plastic breather parts", "means": "The cover itself is the last plastic piece.", "do": "IE billet cover with their can kit."}], "c": {"level": "community", "n": 3, "note": "Vendor material and owner reports."}}, "aftercare": ["Check the can weekly for the first month, then set your own interval. Empty at about 2 inches.", "Clean the separator baffles twice a year (ECS).", "Below freezing: drain weekly, or reconnect the factory hose for the winter. Not a suggestion."], "disagreements": [{"topic": "Recirculate or vent?", "pos": "Some forum builds vent to a filter on the can.", "call": "Recirculate. Every vendor does; venting is messy and illegal."}, {"topic": "Keep the PCV valve?", "pos": "ECS caps the manifold path and keeps a valve-shaped plate; IE and CTS replace the breather plate instead.", "call": "Both work. Pick by which parts you want to stop buying."}, {"topic": "How long?", "pos": "'Under an hour' (IE owners) vs two (ECS routing).", "call": "1.5–2 hr first time."}], "sources": ["ECS Tuning Mk5 FSI baffled oil catch can installation PDF (r4)", "IE catch can product pages (factory cover and billet cover kits)", "CTS Turbo FSI catch can install sheet", "VWVortex 'How-To PCV Catch Can TSI, FSI and TFSI'", "034Motorsport catch can guides (technique)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'catch-can';
update guides set content = $j${"id": "catch-can-tsi", "title": "Oil catch can install (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "catchcan-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which kit?", "hint": "TSI kits all replace the factory PCV with a billet adapter and route the crankcase vent through the can to the turbo inlet. They differ in bracket location and whether the manifold port is capped or kept on a check valve.", "options": [{"id": "ie", "label": "Integrated Engineering", "when": "Billet PCV adapter, -10AN lines, bracket on the strut tower", "brand": true}, {"id": "cts", "label": "CTS Turbo", "when": "Billet PCV plate, braided lines, bracket by the battery", "brand": true}, {"id": "other", "label": "034 / ECS / other", "when": "Same shape; follow the kit sheet", "brand": false}], "brandSpecific": true}, "glance": {"timeFirst": "1.5 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$250–450", "risk": "Winter freeze · lines under the fuel rail", "why": "Same reasoning as the FSI: direct injection never washes the intake valves, so crankcase oil vapour bakes onto them. On the TSI the factory PCV is also the weak point that blows rear main seals, so a catch-can kit that replaces it does two jobs at once.", "note": "Written from the IE and CTS TSI kit documentation and owner installs; not as deeply sourced as the FSI guide, and flagged where it matters."}, "heroCap": "Crankcase vent from the PCV location on the valve cover → baffled can → turbo inlet. The manifold's vacuum port is capped or kept behind a check valve depending on the kit.", "lifespan": {"title": "When owners do this", "headline": ["With a tune, or when the PCV fails and they'd rather not buy another"], "earliest": null, "detail": "Nothing wears; owners add it for carbon and because the billet adapter deletes the failure-prone PCV diaphragm. Tuned TSIs run more crankcase pressure and benefit most.", "factors": ["Tune", "PCV failed", "Oil in the intercooler pipes"], "inspect": ["Check the can weekly at first; empty at about 2 inches"], "confidence": {"level": "community", "n": 3, "note": "Vendor positioning and owner reports."}}, "should": {"yesIf": ["Tuned car", "PCV has failed (again)", "Oil in the charge pipes", "You want to slow intake-valve carbon"], "codes": [], "notes": ["Recirculating kits only; vent-to-atmosphere is messy and illegal.", "Winter: crankcase vapour is mostly water in cold weather and it can freeze in the can and lines. Drain weekly near freezing; below freezing, many owners reconnect the factory route for the season. A frozen vent blows seals.", "Kits differ on the manifold port: some cap it (all vent goes through the can under boost and vacuum), some keep a check valve so idle vacuum still pulls through the can. Follow yours."], "confidence": {"level": "medium", "n": 3, "note": "Reasoning is solid; hardware detail is at kit-sheet level."}}, "parts": [{"tier": "aftermarket", "name": "TSI catch can kit", "pn": "the kit you chose above", "note": "Billet PCV adapter/plate, can, bracket, lines, manifold cap or check valve", "price": "$250–450", "links": []}, {"tier": "oe", "name": "Clean engine oil for o-rings, zip ties", "pn": "—", "note": "", "price": "—", "links": []}], "aftermarket": [{"name": "Integrated Engineering TSI catch can kit", "note": "Billet PCV adapter replaces the factory valve, -10AN braided lines, bracket, T-handle drain. Recirculates to the turbo inlet.", "price": "$350–450", "signal": "Best documented", "links": []}, {"name": "CTS Turbo TSI kit", "note": "Billet PCV plate, braided lines, bracket. Popular with the K04 crowd.", "price": "$250–350", "signal": "Tuner pick", "links": []}, {"name": "034Motorsport / ECS TSI kits", "note": "Same idea, different hardware and bracket placement.", "price": "$300–400", "signal": "Fine choices", "links": []}], "tools": [{"name": "T30 (PCV screws), 10mm and 13mm sockets for the bracket"}, {"name": "AN wrench or taped adjustable, connector release tool, hose-clamp pliers"}], "before": ["Engine cold. Read the kit sheet alongside this.", "Oil every o-ring before threading an AN fitting; never over-tighten.", "Route lines clear of the fuel rail, coil packs and anything hot."], "steps": [{"n": 1, "title": "Cover off, PCV off", "blocks": [{"t": "text", "b": "Engine cover off. Disconnect the PCV vent hose to the manifold at both ends (spring clasps). Remove the factory PCV's Torx screws and lift it off the head; clean the face. See the TSI PCV guide for detail."}, {"t": "ill", "id": "catchcan-hero", "cap": "Same flow as the FSI: vent → can → turbo inlet."}]}, {"n": 2, "title": "Billet adapter on", "blocks": [{"t": "text", "b": "Kit's gasket or o-ring, billet PCV adapter/plate onto the head with the factory or supplied screws, snug (about 4 Nm; small screws into aluminium). Oil the o-ring and thread the feed line's fitting into the adapter by hand, then snug."}, {"t": "torque", "label": "Adapter screws", "nm": 4, "c": {"level": "single", "n": 1, "note": "Kit sheets: snug. Small screws into aluminium."}}]}, {"n": 3, "title": "Manifold port", "blocks": [{"t": "text", "b": "Cap the manifold's PCV port with the kit's plug and clip (IE and most others), or fit the kit's check valve inline if yours keeps the vacuum path. Either way, no open port.", "only": ["ie", "cts", "other"]}]}, {"n": 4, "title": "Mount the can, connect the return", "blocks": [{"t": "text", "b": "Bracket to its point (IE: strut-tower area; CTS: by the battery; per sheet), can loose in the bracket. Return line from the can to the turbo inlet pipe's breather port (the kit supplies the fitting or a hose barb for the factory port). Feed to the can's feed side, return from the return side; they are not interchangeable."}]}, {"n": 5, "title": "Route, tighten, start", "caution": true, "blocks": [{"t": "text", "b": "Walk both lines: under nothing sharp, clear of the fuel rail and coils, no contact with the belt side. Snug the AN fittings, lock the can, cover on. Start it and listen for hiss at the adapter."}, {"t": "warn", "b": "An open or leaking vent is a lean condition and an oil mess. Ten minutes of routing."}]}], "alsoReplace": [{"name": "Rear main seal check", "why": "If the PCV that this replaced had failed, look for oil at the bellhousing."}, {"name": "Turbo inlet coupler", "why": "Hardened factory couplers are a common TSI boost leak; the kit's fitting goes into this pipe anyway."}], "check": {"tab": "Which kit?", "title": "Which kit?", "illId": "catchcan-hero", "illCap": "All three routes end at the turbo inlet.", "rows": [{"see": "Want the most documented install", "means": "IE's kit has the sheet and the videos.", "do": "IE."}, {"see": "Tuned, want the tuner's kit", "means": "CTS.", "do": "CTS."}, {"see": "Already have an 034/ECS can from another car", "means": "Adapter and lines are what you need.", "do": "Buy the TSI PCV adapter and plumb it."}], "c": {"level": "community", "n": 3, "note": "Vendor material."}}, "aftercare": ["Weekly checks at first; empty at 2 inches.", "Winter: drain weekly or reconnect the factory route."], "disagreements": [{"topic": "Cap the manifold port or check-valve it?", "pos": "Kits differ.", "call": "Follow your kit; both work when installed as designed."}], "sources": ["IE and CTS TSI catch can kit documentation and listings", "Owner installs on Mk6 TSI (same engine)", "FSI catch can guide sources (mechanism, winter warning)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'catch-can-tsi';
update guides set content = $j${"id": "turbo-kit-r32", "title": "Turbo kit (complete systems)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "turbo-kit-hero", "alsoFits": "HPA and 034 also sell versions for the Mk4 R32, Audi A3 8P 3.2 and TT 3.2; hardware differs by chassis", "category": "Forced induction", "kind": "upgrade", "variants": {"question": "Which kit are you planning around?", "hint": "Complete systems only: turbo, manifold, downpipe, plumbing, fuelling and software in one box. Piecemeal builds are a different conversation.", "options": [{"id": "dtm", "label": "HPA DTM (EFR 7670, ~7 psi)", "when": "Entry tier. 340 hp on a Mk5 with stock fuelling. The turbo that doesn't feel like a turbo.", "brand": true}, {"id": "ft", "label": "HPA FT-410 / FT-470 (EFR 7670, 16–22 psi)", "when": "Adds the liquid-cooled intake manifold and bigger support parts. 410–470 hp.", "brand": true}, {"id": "ftx", "label": "HPA FTX (EFR 8374)", "when": "500+ hp under 20 psi. The DSG becomes the limit.", "brand": true}, {"id": "o34", "label": "034Motorsport Stage 1 / 2", "when": "$5,895 with software and fuelling; ~300 whp on Stage 1; Stage 2 adds the head spacer.", "brand": true}, {"id": "jdy", "label": "JDY Performance", "when": "Built to order by an R32 specialist; specs by quote.", "brand": true}], "brandSpecific": true}, "glance": {"timeFirst": "3–5 days · 30–40 hr", "timeRepeat": "—", "difficulty": 5, "cost": "$6,000–14,000 kit · $2,000–6,000 in things that aren't in the box", "risk": "Compression, fuelling, heat and a DSG with a torque limit · a wrong step costs an engine", "why": "Naturally aspirated, a 3.2 VR6 makes 250 hp and sounds like the best engine VW ever built. Turbocharged, the same block makes 340 to 500+ with all-wheel drive to put it down. Complete kits from HPA and 034 exist because the VR6 turbo recipe has been worked out over twenty years: a cast manifold that keeps the O2 sensors where the DSG expects them, a compression drop, bigger injectors, software, and heat management. This guide is about choosing a kit, understanding what it does to the car, and everything you'll need that isn't in the box.", "note": "Written from HPA's published tiers and contents, 034's Stage 1 release thread and the R32 community. No complete public install PDF exists for the Mk5, so the install section is a map, not turn-by-turn."}, "heroCap": "Schematic of a single-turbo VR6: exhaust manifold → turbo → downpipe; compressed air → intercooler (air-to-water in HPA's manifold) → intake; oil and coolant lines to the turbo; bigger injectors and software to match. Not a recreation of any kit's install photos.", "lifespan": {"title": "When owners do this", "headline": ["When the car is otherwise sorted and the owner has a plan for the DSG"], "earliest": null, "detail": "Owners who turbo an R32 have usually done the maintenance first (timing chains, coolant pipe, DSG and Haldex service) because the kit puts every one of those under more stress, and because the install has the front of the engine apart anyway.", "factors": ["Maintenance state of the engine", "DSG health (clutch packs are the limit)", "Budget for the parts not in the box"], "inspect": ["Compression test and oil analysis before you spend a dollar on a kit"], "confidence": {"level": "community", "n": 3, "note": "R32 community consensus."}}, "should": {"yesIf": ["You want 340+ hp with AWD and a car that still drives to work", "The engine is healthy (compression test, no chain noise)", "You have a budget for the whole project, not the kit price"], "codes": [], "notes": ["Compression. HPA's kits all include a 4 mm compression-reduction kit (a head spacer, taking the 11.3:1 VR6 to about 7.5:1 on their spec); 034's Stage 1 runs stock compression at low boost and Stage 2 adds a spacer (8.5:1 on the Mk5). A spacer means the head comes off. That's the difference between a two-day and a four-day install and it's the single biggest decision in the project.", {"text": "DTM on a Mk5: HPA states 340 hp rather than 350 because of the stock fuelling on the Mk5. It runs about 7 psi on a stock-compression-ish setup with the spacer; owners describe it as an R32 that pulls harder everywhere rather than a boosted car.", "only": ["dtm"]}, {"text": "FT-410 and FT-470 add HPA's liquid-cooled cast intake manifold (air-to-water intercooling) and run 16–22 psi. That's where the kit stops being a bolt-on and becomes a project: chargecooler plumbing, a coolant loop and pump, and the fuel system that 470 hp asks for.", "only": ["ft"]}, {"text": "FTX (EFR 8374): 500+ hp and 500+ lb-ft under 20 psi. At this level the stock DSG clutch packs are the limit; budget a TCU tune and clutch pack work, or don't buy this tier.", "only": ["ftx"]}, {"text": "034 Stage 1: about 300 whp (280 on stock exhaust), stock compression, FMIC. Their notes say the bumper reinforcement and core support need clearancing for the intercooler and the heat shield for the turbo. Stage 2 adds their head spacer for more boost.", "only": ["o34"]}, {"text": "JDY builds R32 turbo cars for a living; their kits are specified per customer. Ask for the parts list and software plan in writing before you commit, and ask what they assume about the DSG.", "only": ["jdy"]}, "The DSG. The DQ250's clutch packs are the accepted weak point past roughly 400 lb-ft (community figure). Every tier above DTM wants a TCU tune at minimum; FT-470 and FTX want clutch pack upgrades. Plan for it; it's not in any kit.", "Emissions. A turbo kit relocates the cats or removes them, changes the O2 sensor plumbing and adds hardware the factory ECU doesn't expect. HPA's software integrates the emissions controls; even so, this is not a smog-legal modification in most US states. Know your inspection regime."], "confidence": {"level": "medium", "n": 4, "note": "HPA tier contents and numbers from their listings; 034 from their release thread; DSG limits are community figures."}}, "parts": [{"tier": "aftermarket", "name": "Complete turbo kit", "pn": "the kit you chose above", "note": "Turbo, manifold, downpipe, plumbing, injectors, FPR, lines, software, boost controller", "price": "$6,000–14,000", "links": []}, {"tier": "aftermarket", "name": "NOT IN THE BOX: head gasket set, head bolts, timing tools (spacer kits)", "pn": "—", "note": "HPA includes the spacer, not the gasket set or bolts", "price": "$300–500", "links": [], "only": ["dtm", "ft", "ftx", "o34"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: colder plugs (one range), coils if original", "pn": "NGK BKR7EIX or kit spec", "note": "", "price": "$100–300", "links": []}, {"tier": "aftermarket", "name": "NOT IN THE BOX: fuel pump (in-tank) for FT-470 and above", "pn": "per kit maker", "note": "", "price": "$300–600", "links": [], "only": ["ft", "ftx"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: DSG TCU tune; clutch packs for FT-470/FTX", "pn": "HPA / others", "note": "", "price": "$800–4,000", "links": [], "only": ["ft", "ftx"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: gauges (boost, oil pressure, AFR), oil and coolant, exhaust from the downpipe back", "pn": "—", "note": "Your cat-back must meet the kit's downpipe flange", "price": "$500–2,000", "links": []}, {"tier": "oe", "name": "NOT IN THE BOX: every gasket, o-ring and TTY bolt you disturb; new manifold studs", "pn": "—", "note": "", "price": "$200", "links": []}], "aftermarket": [{"name": "HPA Motorsports EFR kits (DTM / FT-410 / FT-470 / FTX)", "note": "The most complete systems for this car: cast manifold with factory-position O2 bungs, stainless downpipe with flex, spacer kit, 500 mL injectors, FPR, plumbing, oil/water lines, software, boost controller. Liquid-cooled intake manifold from FT-410 up. DTM about $8,900.", "price": "$8,900–14,000", "signal": "Most complete", "links": [{"store": "HPA VR6 turbo program", "url": "https://www.hpamotorsports.com/collections/vr6-single-turbo-program"}]}, {"name": "034Motorsport Stage 1 / Stage 2", "note": "Stage 1 $5,895 with hardware, software and fuelling; FMIC; ~300 whp. Stage 2 head spacer for more boost. Mk5 R32 and A3 kits differ in intake, intercooler and plumbing.", "price": "$5,900 + Stage 2", "signal": "Value complete kit", "links": []}, {"name": "JDY Performance", "note": "R32 specialist; turbo programs built to order. Get the spec in writing.", "price": "by quote", "signal": "Specialist build", "links": []}, {"name": "VF Engineering supercharger (alternative)", "note": "The non-turbo route: centrifugal supercharger kit, around 100 hp over stock, stock compression, simpler install. Different character; instant response, no spacer.", "price": "$6,000–7,000", "signal": "Supercharger alternative", "links": []}], "tools": [{"name": "Everything in the PCV and coolant pipe guides (nose forward, manifold off), plus: engine support bar or hoist, torque wrenches ¼\" to ½\" with angle gauge"}, {"name": "Head spacer tiers: 24V cam locks and crank pin, head bolt socket, straight edge; a clean bench", "only": ["dtm", "ft", "ftx"]}, {"name": "AN wrenches, hose-clamp pliers, a die grinder for clearancing (034: bumper beam, core support, heat shield)", "only": ["o34"]}, {"name": "VCDS or equivalent for adaptation and logging; a wideband AFR gauge for the first drives"}], "before": ["Compression test and an oil analysis. A tired engine doesn't get better with boost.", "Do the maintenance first: timing chains if noisy, coolant pipe and thermostat housing, PCV/valve cover, DSG and Haldex service, plugs and coils. The kit stresses every one of them.", "Read the kit's parts list against this guide's 'not in the box' list and order all of it before the car comes apart.", "Book the DSG software at the same time as the engine software; you don't want to drive 400 lb-ft through a stock TCU map while you wait."], "steps": [{"n": 1, "title": "Where the power comes from", "blocks": [{"t": "text", "b": "Stock, the 3.2 VR6 is rated 250 hp and 236 lb-ft. Every complete kit sits somewhere on the chart below; the numbers are the makers' claims, at the crank unless marked, and the Mk5 DTM figure is HPA's own correction for this car's stock fuelling."}, {"t": "chart", "title": "Manufacturer-claimed peak horsepower", "unit": "hp", "baseline": "Stock R32", "bars": [{"label": "Stock R32", "v": 250}, {"label": "034 Stage 1", "v": 300, "note": "whp, kit spec (280 on stock exhaust)"}, {"label": "HPA DTM (Mk5)", "v": 340, "note": "7 psi, stock fuelling"}, {"label": "HPA FT-410", "v": 410, "note": "16 psi"}, {"label": "HPA FT-470", "v": 470, "note": "19–22 psi"}, {"label": "HPA FTX (EFR 8374)", "v": 500, "note": "'500+' under 20 psi"}], "source": "HPA and 034 published figures; 034's is wheel horsepower. Not dyno-verified by this guide.", "c": {"level": "medium", "n": 3, "note": "Manufacturer claims, cross-listed by two retailers."}}, {"t": "text", "b": "Torque is what you feel and what the DSG has to survive:"}, {"t": "chart", "title": "Manufacturer-claimed peak torque", "unit": "lb-ft", "baseline": "Stock R32", "bars": [{"label": "Stock R32", "v": 236}, {"label": "HPA DTM", "v": 360}, {"label": "HPA FT-410", "v": 420}, {"label": "HPA FT-470", "v": 500}, {"label": "HPA FTX", "v": 500, "note": "'500+'"}, {"label": "DQ250 DSG comfort zone", "v": 400, "note": "community figure for stock clutch packs"}], "source": "HPA figures; 034 doesn't publish torque; DSG figure is R32-forum consensus.", "c": {"level": "community", "n": 3, "note": "Torque claims from HPA; DSG limit is community experience."}}]}, {"n": 2, "title": "What comes off", "blocks": [{"t": "text", "b": "Nose to service position; airbox and intake; intake manifold (PCV guide, steps 1–3); both exhaust manifolds and the downpipe with the cats (headers guide, steps 1–4); the cat-back's front section if the kit's downpipe flange differs; belly pans; on 034 kits, the bumper beam and core support for the FMIC. Coolant drained (you're into the cooling system for the turbo's water lines and, on HPA FT kits, the chargecooler loop)."}, {"t": "ill", "id": "turbo-kit-hero", "cap": "Schematic of the finished system. Exhaust side on the firewall side of the VR6; intake side toward the radiator."}]}, {"n": 3, "title": "Compression drop (spacer tiers)", "only": ["dtm", "ft", "ftx", "o34"], "caution": true, "blocks": [{"t": "text", "b": "HPA's spacer kits and 034's Stage 2: the head comes off. Timing chains locked at TDC with the 24V tools, head bolts out in sequence, head off, faces cleaned, spacer between two head gaskets per the kit's sheet, head on with new bolts to the factory sequence and angle, chains re-timed and checked with two turns by hand. This is the timing chain guide's discipline applied to a head job; if the chains and guides are old, this is the moment they get replaced too."}, {"t": "warn", "b": "A head off a VR6 in the car, against the firewall, with the chains behind it: this is the hardest single step in this app. Many owners have the spacer done by a shop and bolt the kit on themselves afterward. That's a legitimate plan."}]}, {"n": 4, "title": "Exhaust side: manifold, turbo, downpipe", "blocks": [{"t": "text", "b": "Kit manifold on with new gaskets and studs (its O2 bungs sit where the factory ones did, which is why the DSG keeps behaving). Turbo to the manifold flange. Heat shield per the kit. Downpipe to the turbo, then to your cat-back's front joint (adapt or replace the front section). O2 sensors into the kit's bungs. Wastegate and boost controller plumbing per the kit."}, {"t": "warn", "b": "Manifold studs, again. New ones, anti-seize, and torque in a criss-cross; a leak here is a ticking you'll chase for weeks."}]}, {"n": 5, "title": "Oil and coolant to the turbo", "caution": true, "blocks": [{"t": "text", "b": "Oil feed from the kit's tap (filter housing or gallery) with the supplied stainless line; oil return to the pan or the kit's fitting, gravity-fed and never uphill. Coolant lines per the kit, tee'd into the heater or block circuit as specified. Route every line away from the manifold and secure it; a chafed oil line on a hot turbo is a fire."}, {"t": "warn", "b": "Return line: no kinks, no uphill run, no small bore. A turbo that can't drain oil smokes out its seals in a week."}]}, {"n": 6, "title": "Intake side: intercooling, manifold, plumbing", "blocks": [{"t": "text", "b": "HPA FT/FTX: the liquid-cooled cast intake manifold replaces the factory manifold; its water core needs a coolant loop with a front heat exchanger and a pump, routed and bled like a second cooling system. DTM: charge plumbing to the factory manifold per the kit.", "only": ["dtm", "ft", "ftx"]}, {"t": "text", "b": "034: front-mount intercooler behind the clearanced bumper beam, charge pipes to the factory manifold; check the FMIC's clearance to the core support before final assembly.", "only": ["o34"]}, {"t": "text", "b": "Injectors (500 mL on HPA kits) into the rail with new o-rings; FPR per the kit; MAF/intake per the kit's inlet. Every silicone joint clamped relaxed first, tight second."}]}, {"n": 7, "title": "Software, then the first start", "caution": true, "blocks": [{"t": "text", "b": "Load the kit's engine software (and the DSG software you booked). New colder plugs. Oil and coolant filled and bled. Crank with coils unplugged to build oil pressure and fill the turbo's line, then start. Idle, watch for leaks at every oil and coolant joint and every exhaust flange. Let it reach temperature; check the chargecooler loop for air if fitted."}, {"t": "warn", "b": "First drives with a wideband AFR gauge and boost gauge in view, at the kit's lowest boost setting. Lean under boost is how VR6s die. Log, don't guess."}]}, {"n": 8, "title": "Break-in and re-check", "blocks": [{"t": "text", "b": "500 gentle miles, then re-torque manifold and downpipe hardware, re-check every clamp and line, change the oil (spacer tiers: the head gasket set's first heat cycles put debris in it). Only then raise boost per the kit's stages."}]}], "alsoReplace": [{"name": "Timing chains and guides", "why": "If the head is coming off for a spacer, the chains are right there. Don't put a turbo on a rattling VR6."}, {"name": "Coolant pipe, thermostat housing, PCV/valve cover", "why": "All under the manifold you're removing anyway."}, {"name": "Clutch packs / TCU software", "why": "FT-470 and FTX: the DSG is the weak link. Budget it as part of the kit."}, {"name": "Brakes and tyres", "why": "Doubling the power on 345 mm brakes and all-seasons is a decision too. R32 brake guides cover pads and rotors; tyres are on you."}, {"name": "Engine and transmission mounts", "why": "Torque doubles; soft mounts let the manifold and downpipe move against everything."}], "check": {"tab": "Which tier?", "title": "Which tier is right for your car?", "illId": "turbo-kit-hero", "illCap": "Power, budget, and how much of the car you're willing to open up.", "rows": [{"see": "Daily driver, want it noticeably faster, no head work", "means": "Low boost, stock-ish compression.", "do": "034 Stage 1 (no spacer) or HPA DTM (spacer included; more complete)."}, {"see": "Want 400+ and will do the head", "means": "Spacer tier with fuelling.", "do": "HPA FT-410; plan the DSG tune."}, {"see": "Want 500 and know what that means for the DSG", "means": "Top tier, clutch packs, full fuel system.", "do": "HPA FTX or a JDY build; budget the transmission."}, {"see": "Want more power with the least disassembly", "means": "Supercharger.", "do": "VF Engineering; a different guide when we write it."}], "c": {"level": "community", "n": 3, "note": "Community consensus plus manufacturer tiering."}}, "aftercare": ["Oil at 500 miles, then every 5k with a turbo-rated oil.", "Log AFR and boost for the first month; a drift is a leak.", "Re-torque exhaust hardware after the first heat cycles.", "Watch coolant level daily for two weeks: the chargecooler loop and the turbo lines are new places to leak."], "disagreements": [{"topic": "Spacer or not?", "pos": "034 Stage 1 runs stock compression; HPA includes a spacer in every tier.", "call": "Low boost can live at stock compression; anything you'll want more from later wants the spacer, and doing it once is cheaper than twice."}, {"topic": "DSG limit", "pos": "Figures from 350 to 450 lb-ft on the forums.", "call": "Treat 400 as the line and tune the TCU at any tier above DTM."}, {"topic": "Home install?", "pos": "Vendors say 'for your technician'.", "call": "5 out of 5. The bolt-on parts are within reach of someone who's done the manifold-off jobs in this app; the spacer is where most owners bring in a shop."}], "sources": ["HPA Motorsports EFR single-turbo program (tiers, contents, Mk5 fuelling note) via UroTuning and GMP listings", "Audizine: 034Motorsport 3.2 24V VR6 Stage 1 turbo kit release thread (price, whp, clearancing, Stage 2 spacer)", "VWVortex R32 forced-induction and DSG threads (clutch pack limits)", "Motorsport Calibrations R32 turbo build guide (context for big-turbo territory)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'turbo-kit-r32';
